      <div class="compare-card__footer">
        <span>${ti(t.deltaLabel)}: ${ti(t.previousValue)}</span>
        <span class="compare-card__delta ${wh[t.severity]||wh.info}">${ti(t.deltaValue)}</span>
      </div>
